package com.fitlife.usuario.repository;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.RowMapper;import org.springframework.stereotype.Repository;import org.springframework.dao.EmptyResultDataAccessException;
@Repository public class UsuarioRepository {
 private final JdbcTemplate jdbc; private final ObjectMapper mapper; public UsuarioRepository(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
 private final RowMapper<Map<String,Object>> mapperRow=(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",rs.getLong("id"));m.put("nome",rs.getString("nome"));m.put("data_nasc",rs.getString("data_nasc"));m.put("cpf",rs.getString("cpf"));m.put("genero",rs.getString("genero"));m.put("telefone",rs.getString("telefone"));m.put("endereco",rs.getString("endereco"));m.put("email",rs.getString("email"));m.put("peso",rs.getBigDecimal("peso"));m.put("altura",rs.getBigDecimal("altura"));m.put("sexo",rs.getString("sexo"));m.put("frequencia",rs.getString("frequencia"));m.put("atividade",rs.getString("atividade"));m.put("cardiopatia",rs.getString("cardiopatia"));m.put("fumo",rs.getString("fumo"));m.put("alcool",rs.getString("alcool"));try{String s=rs.getString("saude_json");m.put("saude",s==null?List.of():mapper.readValue(s,List.class));}catch(Exception e){m.put("saude",List.of());}m.put("restricao",rs.getString("restricao"));m.put("objetivo",rs.getString("objetivo"));m.put("objetivoMedico",rs.getString("objetivo_medico"));m.put("fotoUrl",rs.getString("foto_url"));return m;};
 public Map<String,Object> buscarPorId(long id){try{return jdbc.queryForObject("SELECT * FROM usuario WHERE id=?",mapperRow,id);}catch(EmptyResultDataAccessException e){return null;}}
 public Map<String,Object> buscarPorEmail(String email){try{return jdbc.queryForMap("SELECT id,nome,email,senha_hash FROM usuario WHERE LOWER(email)=LOWER(?)",email);}catch(EmptyResultDataAccessException e){return null;}}
 public long inserir(Map<String,Object>d,String senhaHash){String sql="INSERT INTO usuario(nome,data_nasc,cpf,genero,telefone,endereco,email,senha_hash,peso,altura,sexo,frequencia,atividade,cardiopatia,fumo,alcool,saude_json,restricao,objetivo,objetivo_medico) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
  String data=text(d,"data_nasc",text(d,"nascimento",null)); String saude=writeJson(d.get("saude"));
  jdbc.update(sql,text(d,"nome",null),data,text(d,"cpf",null),text(d,"genero",text(d,"sexo",null)),text(d,"telefone",null),text(d,"endereco",null),text(d,"email",null),senhaHash,decimal(d.get("peso")),decimal(d.get("altura")),text(d,"sexo",null),text(d,"frequencia",null),text(d,"atividade",null),text(d,"cardiopatia",null),text(d,"fumo",null),text(d,"alcool",null),saude,text(d,"restricao",null),text(d,"objetivo",null),text(d,"objetivoMedico",text(d,"objetivo_medico",null)));
  return jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);
 }
 public Map<String,Object> atualizarPerfil(long id,Map<String,Object>d){jdbc.update("UPDATE usuario SET email=?,genero=?,telefone=?,endereco=? WHERE id=?",text(d,"email",null),text(d,"genero",null),text(d,"telefone",null),text(d,"endereco",null),id);return buscarPorId(id);}
 public Map<String,Object> atualizarMedico(long id,Map<String,Object>d){jdbc.update("UPDATE usuario SET peso=?,altura=?,saude_json=?,restricao=?,objetivo_medico=? WHERE id=?",decimal(d.get("peso")),decimal(d.get("altura")),writeJson(d.get("saude")),text(d,"restricao",null),text(d,"objetivoMedico",null),id);return buscarPorId(id);}
 public void atualizarFoto(long id,String url){jdbc.update("UPDATE usuario SET foto_url=? WHERE id=?",url,id);}
 private String text(Map<String,Object>d,String k,String def){Object v=d.get(k);return v==null?def:v.toString();}
 private java.math.BigDecimal decimal(Object v){if(v==null||v.toString().isBlank())return null;try{return new java.math.BigDecimal(v.toString());}catch(NumberFormatException e){return null;}}
 private String writeJson(Object v){try{return v==null?"[]":mapper.writeValueAsString(v);}catch(JsonProcessingException e){return "[]";}}
}
